import logging
import sys

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("ledgerbook")

DB = {
    "2026-09": [
        {"merchant": "Blue Bottle", "amount_cents": 1850},
        {"merchant": "Office Depot", "amount_cents": 12750},
    ]
}


@mcp.tool()
def list_expenses(month: str) -> list[dict]:
    """List expense entries for a month, e.g. 2026-09."""
    return DB.get(month, [])


@mcp.tool()
def add_expense(month: str, merchant: str, amount_cents: int) -> dict:
    """Record one expense entry for a month."""
    DB.setdefault(month, []).append(
        {"merchant": merchant, "amount_cents": amount_cents}
    )
    return {"month": month, "merchant": merchant, "amount_cents": amount_cents}


def main() -> None:
    logging.basicConfig(level=logging.INFO, stream=sys.stderr)
    mcp.run()


if __name__ == "__main__":
    main()

